mapper.select:
SELECT DISTINCT
ADJ_VERSION
FROM
T_MP_ADJUST_MATERIAL_LOG
WHERE
IS_DELETE = 0 AND ADJ_VERSION IS NOT NULL
AND FACTORY_CODE = #{factoryCode}
AND YEAR = #{year}
AND MONTH = #{month}
AND ADJUST_TYPE = #{adjustType}
ORDER BY ADJ_VERSION DESC

mapper.delete:
DELETE FROM T_MP_ADJUST_MATERIAL_LOG
WHERE FACTORY_CODE = #{factoryCode} AND YEAR= #{year} AND MONTH= #{month}
AND ADJ_VERSION= #{version}
